import{state}from"./state.js";import{changePin}from"./api.js";import{showToast,closeModal,openModal}from"./utils.js";export function openChangePinModal(){document.getElementById("old-pin").value="",document.getElementById("new-pin").value="",openModal("change-pin-modal")}export async function saveNewPin(){const e=document.getElementById("old-pin").value,n=document.getElementById("new-pin").value;if(!n||n.length<6)return showToast("Новый пароль должен быть не менее 6 символов","error");const t=await changePin(e,n,state.role);t.success?(showToast("Пароль успешно изменен","success"),closeModal("change-pin-modal")):showToast(t.error||"Ошибка при смене пароля","error")}export async function saveNewPinInline(){const e=document.getElementById("settings-old-pin-inline").value,n=document.getElementById("settings-new-pin-inline").value;if(!n||n.length<6)return showToast("Новый пароль должен быть не менее 6 символов","error");const t=await changePin(e,n,state.role);t.success?(showToast("Пароль успешно изменен","success"),document.getElementById("settings-old-pin-inline").value="",document.getElementById("settings-new-pin-inline").value=""):showToast(t.error||"Ошибка при смене пароля","error")}